sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);

	function TestCase_GetStatus(aWhiteListPlugins, aWhiteListStoreApps, vExpected)
	{
		function TestCase_GetStatus_CheckResult(vInput,vExpected,vResult)
		{
			if (x_snc_devtools.IsObject(vExpected) == true)
			{
				var aPlugins = x_snc_devtools.GetArrayValue(x_snc_devtools.GetValue(vResult,'plugins'));
				var aStoreApps = x_snc_devtools.GetArrayValue(x_snc_devtools.GetValue(vResult,'store_apps'));

				var vExpectedPlugins = x_snc_devtools.GetValue(vExpected,'plugins');
				if (vExpectedPlugins == 'all')
				{
					if (aPlugins.length < 500)
					{
						return false;
					}
				}
				if (vExpectedPlugins != aPlugins.length)
				{
					return false;
				}

				var vExpectedStoreApps = x_snc_devtools.GetValue(vExpected,'store_apps');
				if (vExpectedStoreApps == 'all')
				{
					if (aStoreApps.length < 500)
					{
						return false;
					}
				}
				if (vExpectedStoreApps != aStoreApps.length)
				{
					return false;
				}
			}

			return true;
		}

		test.TestCase(
			'Function GetStatus()',
			GetStatus,
			{
				aWhiteListPlugins: aWhiteListPlugins,
				aWhiteListStoreApps: aWhiteListStoreApps
			},
			null,
			TestCase_GetStatus_CheckResult);
	}

	var aWhiteListPlugins = [];
	var aWhiteListStoreApps = [];
	TestCase_GetStatus(aWhiteListPlugins, aWhiteListStoreApps, { plugins: 0, store_apps: 0});




	var aWhiteListPluginSysIds = [];
	var aWhiteListPluginIds = [];
	var aWhiteListPluginNames = [];
	var aWhiteListPluginMixed = [];

	var grPlugin = new GlideRecord('sys_plugins');
	grPlugin.setLimit(5);
	grPlugin.query();
	var nMixed = 0;
	while (grPlugin.next())
	{
		aWhiteListPluginSysIds.push(x_snc_devtools.GetStringValue(grPlugin.sys_id));
		aWhiteListPluginIds.push(x_snc_devtools.GetStringValue(grPlugin.source));
		aWhiteListPluginNames.push(x_snc_devtools.GetStringValue(grPlugin.name));

		if (nMixed == 0)
		{
			aWhiteListPluginMixed.push(x_snc_devtools.GetStringValue(grPlugin.sys_id));
		}
		else if (nMixed == 1)
		{
			aWhiteListPluginMixed.push(x_snc_devtools.GetStringValue(grPlugin.source));
		}
		else if (nMixed == 2)
		{
			aWhiteListPluginMixed.push(x_snc_devtools.GetStringValue(grPlugin.name));
		}		

		nMixed++;
		if (nMixed == 3)
		{
			nMixed = 0;
		}
	}

	TestCase_GetStatus(aWhiteListPluginSysIds, null,{ plugins: 5, store_apps: 0 });
	TestCase_GetStatus(aWhiteListPluginIds, null,{ plugins: 5, store_apps: 0 });
	TestCase_GetStatus(aWhiteListPluginNames, null,{ plugins: 5, store_apps: 0 });
	TestCase_GetStatus(aWhiteListPluginMixed, null, { plugins: 5, store_apps: 0 });


	var aWhiteListStoreAppSysIds = [];
	var aWhiteListStoreAppScopes = [];
	var aWhiteListStoreAppNames = [];
	var aWhiteListStoreAppMixed = [];

	var grStoreApp = new GlideRecord('sys_store_app');
	grStoreApp.setLimit(5);
	grStoreApp.query();
	var nMixed = 0;
	while (grStoreApp.next())
	{
		aWhiteListStoreAppSysIds.push(x_snc_devtools.GetStringValue(grStoreApp.sys_id));
		aWhiteListStoreAppScopes.push(x_snc_devtools.GetStringValue(grStoreApp.scope));
		aWhiteListStoreAppNames.push(x_snc_devtools.GetStringValue(grStoreApp.name));

		if (nMixed == 0)
		{
			aWhiteListStoreAppMixed.push(x_snc_devtools.GetStringValue(grStoreApp.sys_id));
		}
		else if (nMixed == 1)
		{
			aWhiteListStoreAppMixed.push(x_snc_devtools.GetStringValue(grStoreApp.scope));
		}
		else if (nMixed == 2)
		{
			aWhiteListStoreAppMixed.push(x_snc_devtools.GetStringValue(grStoreApp.name));
		}		

		nMixed++;
		if (nMixed == 3)
		{
			nMixed = 0;
		}
	}

	TestCase_GetStatus(null,aWhiteListStoreAppSysIds,{ plugins: 0, store_apps: 5 });
	TestCase_GetStatus(null,aWhiteListStoreAppScopes,{ plugins: 0, store_apps: 5 });
	TestCase_GetStatus(null,aWhiteListStoreAppNames,{ plugins: 0, store_apps: 5 });
	TestCase_GetStatus(null,aWhiteListStoreAppMixed,{ plugins: 0, store_apps: 5 });

	TestCase_GetStatus(aWhiteListPluginSysIds,aWhiteListStoreAppSysIds,{ plugins: 5, store_apps: 5 });
	TestCase_GetStatus(aWhiteListPluginIds,aWhiteListStoreAppScopes,{ plugins: 5, store_apps: 5 });
	TestCase_GetStatus(aWhiteListPluginNames,aWhiteListStoreAppNames,{ plugins: 5, store_apps: 5 });
	TestCase_GetStatus(aWhiteListPluginMixed,aWhiteListStoreAppMixed,{ plugins: 5, store_apps: 5 });



	TestCase_GetStatus(['all'],['all'],{ plugins: 'all', store_apps: 'all' });
	

	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
